142			default:
143				b.WriteString("x")
144			}
145		}
146		text := b.String()
147		if m := schemeRe.FindString(text); m != "" {
148			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m))
149		} else if m := domainRe.FindStringSubmatch(text); m != nil {
150			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("domain %q is not allowed; use {{campaign_url}}", m[1]))
151		} else if m := ipRe.FindStringSubmatch(text); m != nil {
152			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("address %q is not allowed; use {{campaign_url}}", m[1]))
153		}
154		if m := emailRe.FindString(text); m != "" {
155			res.Error(path, validation.EmailNotAllowed, fmt.Sprintf("email address %q is not allowed", m))
156		}
157		if m := htmlRe.FindString(text); m != "" {
158			res.Error(path, validation.HTMLNotAllowed, fmt.Sprintf("HTML %q is not allowed; copy is plain text", m))
159		}
160	}
161	
162	func lookup(doc any, a, b string) (string, bool) {
163		m, _ := doc.(map[string]any)
164		inner, _ := m[a].(map[string]any)
165		s, ok := inner[b].(string)
