1	package content
2	
3	import (
4		"bytes"
5		"cmp"
6		"fmt"
7		"regexp"
8		"slices"
9		"strings"
10		"unicode/utf8"
11	
12		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
13		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
14	)
15	
16	// Rendered length limits (runes, worst case). They match the maxLength of the
17	// raw templates in schemas/content.schema.json; content_test.go checks that.
18	const (
19		SMSMaxChars     = 160
20		SubjectMaxChars = 80
21	)
22	
23	// Content is validated copy.
24	type Content struct {
25		SMSBody      string
26		EmailSubject string
27		EmailBody    string
28		// SMS is the pessimistic estimate: longest variable values, and Turkish
29		// letters in names and city.
30		SMS SMSInfo
31	}
32	
33	// Banned patterns. They are checked on the text with every variable filled
34	// in by a placeholder, so "{{city}}.com" is caught too. {{campaign_url}} is
35	// the one allowed link and is filled with a space.
36	var (
37		schemeRe = regexp.MustCompile(`(?i)[a-z][a-z0-9+.\-]*://|www\.`)
38		// A bare domain: dot-separated labels ending in a common TLD. Labels are
39		// Unicode-aware, so a Cyrillic lookalike such as "іnsider.com" is caught.
40		domainRe = regexp.MustCompile(`(?i)(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+` +
41			`(?:com|net|org|info|biz|io|co|ai|app|dev|me|ly|gl|to|cc|tv|xyz|link|shop|store|site|online|tr|eu|uk|de|us))(?:$|[^\p{L}\p{N}_-])`)
42		ipRe    = regexp.MustCompile(`(?:^|[^\p{N}.])(\d{1,3}(?:\.\d{1,3}){3})(?:$|[^\p{N}.])`)
43		emailRe = regexp.MustCompile(`[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+`)
44		htmlRe  = regexp.MustCompile(`<\s*/?\s*[A-Za-z][^>]*>`)
45	)
46	
47	// ValidateJSON parses and validates content given as raw JSON.
48	func ValidateJSON(set *schema.Set, data []byte) (Content, validation.Result) {
49		doc, err := schema.Decode(bytes.NewReader(data))
50		if err != nil {
51			var res validation.Result
52			res.Error("", validation.InvalidJSON, err.Error())
53			return Content{}, res
54		}
55		return Validate(set, doc)
56	}
57	
58	// Validate checks decoded content (from schema.Decode): the schema first,
59	// then templates, banned links, emails and HTML, and the worst-case rendered
60	// length. Every problem is reported. SMS encoding and segment count are
61	// warnings only.
62	func Validate(set *schema.Set, doc any) (Content, validation.Result) {
63		var res validation.Result
64		rawTooLong := map[string]bool{}
65		if err := set.Validate(schema.Content, doc); err != nil {
66			for _, is := range schema.Issues(err, "") {
67				res.Errors = append(res.Errors, is)
68				if is.Code == validation.TooLong {
69					rawTooLong[is.Path] = true
70				}
71			}
72		}
73	
74		fields := []struct {
75			path, a, b string
76			limit      int
77		}{
78			{"/sms/body", "sms", "body", SMSMaxChars},
79			{"/email/subject", "email", "subject", SubjectMaxChars},
80			{"/email/body", "email", "body", 0},
81		}
82		var smsParts []Part
83		values := map[string]string{}
84		for _, f := range fields {
85			s, ok := lookup(doc, f.a, f.b)
86			if !ok {
87				continue // the schema already reported it
88			}
89			values[f.path] = s
90			parts, issues := Parse(s)
91			for _, is := range issues {
92				res.Error(f.path, is.Code, is.Message)
93			}
94			checkBans(&res, f.path, parts)
95			if len(issues) > 0 {
96				continue // lengths of a broken template mean nothing
97			}
98			if f.limit > 0 && !rawTooLong[f.path] {
99				if n := utf8.RuneCountInString(worstCase(parts, false)); n > f.limit {
100					res.Error(f.path, validation.RenderedTooLong, fmt.Sprintf(
101						"can render up to %d characters with the longest variable values; the limit is %d", n, f.limit))
102				}
103			}
104			if f.path == "/sms/body" {
105				smsParts = parts
106			}
107		}
108	
109		var info SMSInfo
110		if smsParts != nil {
111			info = MeasureSMS(worstCase(smsParts, true))
112			if info.Segments > 1 {
113				msg := fmt.Sprintf("%s, %d segments in the worst case", info.Encoding, info.Segments)
114				if plain := MeasureSMS(worstCase(smsParts, false)); plain.Encoding != info.Encoding {
115					msg += fmt.Sprintf(" (names or city may contain Turkish letters such as ş, ğ, ı that switch the SMS to UCS-2; without them: %s, %d segment(s))", plain.Encoding, plain.Segments)
116				}
117				res.Warn("/sms/body", validation.SMSMultiSegment, msg)
118			}
119		}
120	
121		slices.SortStableFunc(res.Errors, func(a, b validation.Issue) int { return cmp.Compare(a.Path, b.Path) })
122		if !res.OK() {
123			return Content{}, res
124		}
125		return Content{
126			SMSBody:      values["/sms/body"],
127			EmailSubject: values["/email/subject"],
128			EmailBody:    values["/email/body"],
129			SMS:          info,
130		}, res
131	}
132	
133	// checkBans reports links, email addresses and HTML in the literal text.
134	func checkBans(res *validation.Result, path string, parts []Part) {
135		var b strings.Builder
136		for _, p := range parts {
137			switch {
138			case p.Var == "":
139				b.WriteString(p.Text)
140			case p.Var == "campaign_url":
141				b.WriteString(" ")
142			default:
143				b.WriteString("x")
144			}
145		}
146		text := b.String()
